"""Coverage calibration, score filtering and exact release-bank sizing."""
from fractions import Fraction

import numpy as np

PADDING = 1514
VALUE_MAX = 3028


class _Exceeded(Exception):
    """Internal signal: the distinct exact-key count provably reached the cap."""


def _covers(intervals, low, high):
    for start, end in intervals:
        if start <= low and high <= end:
            return True
    return False


def _count_union(boxes, limit):
    """Exact ``min(|union of boxes|, limit)`` for a single pattern length.

    ``boxes`` is a list of per-coordinate tuples of inclusive integer
    sub-intervals (padding value already excluded). The recursion decomposes
    each coordinate into elementary intervals induced by the active boxes and
    memoizes on the active set, aborting as soon as the cap is provably met.
    """
    if not boxes:
        return 0
    length = len(boxes[0][0])
    suffix = []
    for box in boxes:
        sizes = [0]*(length+1)
        running = 1
        for coordinate in range(length-1, -1, -1):
            running *= sum(end-start+1 for start, end in box[coordinate])
            sizes[coordinate] = running
        suffix.append(sizes)
    if max(box[0][0] for box in suffix if False or True) >= 0:  # placeholder
        pass
    memo = {}
    accumulated = 0

    def walk(depth, active, need):
        nonlocal accumulated
        if depth == length:
            return 1
        if not active:
            return 0
        best = 0
        for box in active:
            if suffix[box][depth] > best:
                best = suffix[box][depth]
        if best >= need:
            raise _Exceeded()
        key = (depth, active)
        found = memo.get(key)
        if found is not None:
            accumulated += found
            if accumulated >= limit:
                raise _Exceeded()
            return found
        points = set()
        for box in active:
            for start, end in box[depth]:
                points.add(start)
                points.add(end+1)
        points = sorted(points)
        total = 0
        for index in range(len(points)-1):
            low = points[index]
            high = points[index+1]-1
            values = (high-low+1) - (1 if low <= PADDING <= high else 0)
            if values <= 0:
                continue
            sub = tuple(box for box in active if _covers(box[depth], low, high))
            if not sub:
                continue
            inner = walk(depth+1, sub, limit-accumulated)
            total += values*inner
            accumulated = accumulated + values*inner
            if accumulated >= limit:
                raise _Exceeded()
        memo[key] = total
        return total

    try:
        return walk(0, tuple(range(len(boxes))), limit)
    except _Exceeded:
        return limit


def exact_bank_entries(patterns, limit):
    """``min(distinct exact keys, limit)`` over all kept patterns."""
    if limit <= 0:
        return 0
    groups = {}
    for pattern in patterns:
        coordinates = []
        empty = False
        for low, high in pattern:
            parts = []
            if low <= PADDING-1:
                parts.append((low, min(high, PADDING-1)))
            if high >= PADDING+1:
                parts.append((max(low, PADDING+1), high))
            if not parts:
                empty = True
                break
            coordinates.append(tuple(parts))
        if empty:
            continue
        coordinates = tuple(coordinates)
        groups.setdefault(len(coordinates), set()).add(coordinates)
    total = 0
    for length in sorted(groups):
        boxes = sorted(groups[length])
        if any(sum(end-start+1 for start, end in box[index]) == 0
               for box in boxes for index in range(length)):
            continue
        total += _count_union(boxes, limit-total)
        if total >= limit:
            return limit
    return total


def matching_rows(automaton, rows):
    """Rows matched by each pattern of the release automaton.

    Returns a list (one entry per priority rank) of boolean arrays over rows.
    """
    rows_count = len(rows)
    hits = np.zeros((len(automaton.ids), rows_count), dtype=bool) if automaton.ids else None
    for index, values in enumerate(rows):
        if not values:
            continue
        ranks = automaton.match_anywhere(values)
        if len(ranks):
            hits[np.asarray(ranks, dtype=np.int64), index] = True
    return hits


def calibrate(clusters, validation_rows, threshold, classes, automaton):
    """Attach exact ``hits``, ``score`` and ``kept`` to every cluster."""
    counts = np.zeros(classes, dtype=np.int64)
    for row in validation_rows:
        counts[row['class']] += 1
    if automaton.ids:
        table = matching_rows(automaton, [row['values'][:_real(row['values'])]
                                          for row in validation_rows])
    else:
        table = None
    threshold = Fraction(threshold[0], threshold[1])
    for cluster in clusters:
        hits = [0]*classes
        if table is not None:
            matched = np.nonzero(table[cluster['rank']])[0]
            for index in matched:
                hits[validation_rows[index]['class']] += 1
        target = cluster['class']
        numerator = Fraction(hits[target], int(counts[target])) if counts[target] else Fraction(0)
        other = [Fraction(hits[c], int(counts[c])) for c in range(classes)
                 if c != target and counts[c]]
        outer = max(other) if other else Fraction(0)
        score = numerator/(outer + Fraction(1, 10000))
        cluster['hits'] = hits
        cluster['score'] = score
        cluster['kept'] = bool(score > threshold)
    return clusters


def _real(values):
    for index, value in enumerate(values):
        if value == PADDING:
            return index
    return len(values)
